    fn chain_family_display_lowercase() {
        assert_eq!(ChainFamily::Solana.to_string(), "solana");
        assert_eq!(ChainFamily::Evm.to_string(), "evm");
        assert_eq!(ChainFamily::Hyperliquid.to_string(), "hyperliquid");
    }

    #[test]
