        .map_err(|e| anyhow::anyhow!("{e}"))?;
    args.add(&t.address).map_err(|e| anyhow::anyhow!("{e}"))?;
    args.add(&t.filter_spec)
        .map_err(|e| anyhow::anyhow!("{e}"))?;
